// Gate + normalise before any billable work happens (§4.7).
//
// Auth: shared secret compared against LQ_WEBHOOK_AUTH_TOKEN. If that env var
// is unset the webhook is open, which mirrors the FastAPI service's behaviour
// so `docker compose up` works with no keys at all.
//
// Idempotency key: client-supplied, else derived as `domain:YYYY-MM-DD`.
// A readable composite beats a hash here — same collapsing behaviour for
// accidental duplicate submissions inside the day bucket, but a reviewer can
// read the key straight out of the table.

const expected = ($env.LQ_WEBHOOK_AUTH_TOKEN || '').trim();
const out = [];

for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const body = item.json.body || {};

  const supplied = String(headers['x-auth-token'] || '');
  const authorized = expected === '' || supplied === expected;

  // Same normalisation as QualifyRequest._normalize_domain in the API, so the
  // idempotency key is derived from the identical string the API scores.
  let domain = String(body.domain || '').trim().toLowerCase();
  domain = domain.replace(/^https?:\/\//, '').split('/')[0];
  const valid_domain = domain.length >= 3 && domain.includes('.');

  const bucket = new Date().toISOString().slice(0, 10);
  const idempotency_key = String(body.idempotency_key || '').trim() || `${domain}:${bucket}`;

  out.push({
    json: {
      authorized,
      valid_domain,
      domain,
      idempotency_key,
      received_at: new Date().toISOString(),
    },
  });
}

return out;

// Single place where a /qualify attempt is judged, fed by BOTH outputs of the
// HTTP node: the normal output (any status code, because neverError is on) and
// the error output (a genuine transport failure — DNS, refused, timeout).
//
// Retryable == transport-shaped only (status 0 or 5xx, minus 503 cost-ceiling).
// A typed 422 from the API is deterministic: re-sending the identical request
// would just burn another full enrichment + LLM pipeline for the same answer.
// This is exactly why the retry loop is hand-built instead of using the HTTP
// node's own retryOnFail, which cannot distinguish the two (§4.2).

const raw = $input.first().json;
const attempt = $runIndex + 1;

let statusCode = Number(raw.statusCode ?? 0);
let body = raw.body ?? null;
let transport_error = null;

if (!raw.statusCode) {
  // Error output: dig the message out of whatever shape n8n handed us.
  const e = raw.error ?? raw;
  statusCode = Number(e.httpCode ?? e.statusCode ?? 0) || 0;
  transport_error = String(e.message ?? e.description ?? JSON.stringify(e));
  body = e.body ?? null;
}

if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (err) { body = { detail: body }; }
}
body = body ?? {};

const ok = statusCode === 200;

// 503 is the daily cost ceiling (§4.7) — a budget decision, not a hiccup.
// Retrying it four seconds later cannot help and would mask the signal.
const retryable = !ok && (statusCode === 0 || (statusCode >= 500 && statusCode !== 503));

const last_error = ok
  ? null
  : (transport_error
      ?? body.detail
      ?? `${body.error ?? 'http_error'}: ${JSON.stringify(body).slice(0, 500)}`);

return [{
  json: {
    ok,
    retryable,
    attempt,
    status_code: statusCode,
    last_error,
    body,
    domain: $('Validate & Derive Key').first().json.domain,
    idempotency_key: $('Validate & Derive Key').first().json.idempotency_key,
  },
}];

// Retries are exhausted or the failure was never retryable. Turn it into a
// dead-letter row whose failure_stage matches the CHECK constraint in
// migrations/001_init.sql, so the DLQ stays queryable by stage (§4.4).

const r = $input.first().json;
const meta = $('Validate & Derive Key').first().json;

const ALLOWED = ['enrichment', 'llm', 'schema', 'network', 'cost_ceiling', 'unknown'];

// The API names its own stage in the typed error body; that is authoritative.
// Anything else is classified from the status code.
let failure_stage = r.body?.stage;
if (!ALLOWED.includes(failure_stage)) {
  if (r.status_code === 0 || r.status_code >= 500) failure_stage = 'network';
  else failure_stage = 'unknown';
}

// Client-visible status: pass the API's typed status straight through so the
// caller sees 422 vs 503 vs 502, not a flattened 500.
const response_status = r.status_code === 0 ? 502 : r.status_code;

return [{
  json: {
    domain: meta.domain,
    idempotency_key: meta.idempotency_key,
    failure_stage,
    last_error: String(r.last_error ?? 'unknown failure').slice(0, 4000),
    attempt_count: r.attempt,
    response_status,
    payload_snapshot: JSON.stringify({
      request: { domain: meta.domain, idempotency_key: meta.idempotency_key },
      received_at: meta.received_at,
      status_code: r.status_code,
      response_body: r.body,
      attempts: r.attempt,
      execution_id: $execution.id,
    }),
  },
}];
